<script setup lang="ts">
definePageMeta({middleware:['auth','supplier']})
const supabase=useSupabaseClient(); const {company,profile,loadProfile}=useProfile(); const stats=reactive({active:0,total:0,sold:0,draft:0,wanted:0}); const loading=ref(true)
onMounted(async()=>{await loadProfile(); if(!isValidUuid(company.value?.id)){loading.value=false;return} const base=()=>supabase.from('parts').select('*',{count:'exact',head:true}).eq('seller_company_id',company.value.id); const [a,t,s,d]=await Promise.all([base().eq('status','active'),base(),base().eq('status','sold'),base().eq('status','draft')]); stats.active=a.count||0;stats.total=t.count||0;stats.sold=s.count||0;stats.draft=d.count||0; const w=await supabase.from('wanted_requests').select('*',{count:'exact',head:true}).eq('status','open'); stats.wanted=w.count||0; loading.value=false})
</script>
<template><section class="section"><div class="container"><div class="kicker">Supplier portal</div><h1 class="page-title" style="margin-top:8px;">Supplier Dashboard</h1><p class="muted" v-if="company">{{company.name}} · {{profile?.full_name}}</p><div class="grid grid-4" style="margin-top:24px;"><div class="card stat"><strong>{{loading?'—':stats.active}}</strong><span class="muted">Active listings</span></div><div class="card stat"><strong>{{loading?'—':stats.total}}</strong><span class="muted">Total listings</span></div><div class="card stat"><strong>{{loading?'—':stats.draft}}</strong><span class="muted">Draft listings</span></div><div class="card stat"><strong>{{loading?'—':stats.sold}}</strong><span class="muted">Parts sold</span></div></div><div class="grid grid-3" style="margin-top:22px;"><div class="card" style="padding:22px;"><h2>Inventory</h2><p class="muted">Create, edit and manage live marketplace listings.</p><div style="display:flex;gap:10px;flex-wrap:wrap;"><NuxtLink class="btn btn-primary" to="/supplier/parts/new">Add Part</NuxtLink><NuxtLink class="btn btn-secondary" to="/supplier/parts">Manage Parts</NuxtLink></div></div><div class="card" style="padding:22px;"><h2>Wanted Parts</h2><p class="muted">{{stats.wanted}} open requests from repairers are waiting for supplier offers.</p><NuxtLink class="btn btn-primary" to="/supplier/wanted">Browse Wanted Parts</NuxtLink></div><div class="card" style="padding:22px;"><h2>Company Profile</h2><p class="muted">Keep your business details, location and logo up to date.</p><NuxtLink class="btn btn-secondary" to="/account/company">Manage Company</NuxtLink></div></div></div></section></template>
